from pathlib import Path
import hashlib,json,os,shutil,subprocess,sys,re
roots=[Path(p).resolve() for p in sys.argv[3:]]
probes={name:Path(path).resolve() for name,path in zip(('baseline','candidate'),sys.argv[1:3])}
out=Path(os.environ.get('PAIRS_OUT','target/pairs')).resolve();out.mkdir(exist_ok=True,parents=True)
record={'probes':{k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in probes.items()},'sources':{str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(Path('crates/journals/src').rglob('*.rs'))},'cells':[]}
for root in roots:
    name=root.parent.name+'-'+root.name;work=out/name;work.mkdir(exist_ok=True)
    cell={'name':name,'requests':{p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in ('request.json','floor.json')},'trials':[]}
    database=work/'data'
    for filename in ('request.json','floor.json'):
        source=(root/filename).read_text()
        source,count=re.subn(r'"database"\s*:\s*"(?:[^"\\]|\\.)*"',lambda _: '"database":'+json.dumps(str(database/'kassiber.sqlite3')),source,count=1)
        assert count==1
        (work/filename).write_text(source)
    for trial in range(int(os.environ.get('PAIRS_RUNS','5'))):
        pair={}
        for engine in (['baseline','candidate'] if trial%2==0 else ['candidate','baseline'])+['floor']:
            database=work/'data'
            if database.exists():shutil.rmtree(database)
            shutil.copytree(root/'base',database)
            request_path=work/('floor.json' if engine=='floor' else 'request.json')
            load=os.getloadavg();probe=probes['candidate' if engine=='floor' else engine]
            result=subprocess.run([str(probe)],input=str(request_path)+'\n',capture_output=True,text=True,check=True)
            value=json.loads(result.stdout)
            if not value['ok']:raise RuntimeError(str(value)[:1000])
            pair[engine]={k:value[k] for k in ('cpu_seconds','seconds','phases') if k in value}|{'load':load,'exact_dump':True}
            shutil.rmtree(database)
        cell['trials'].append(pair)
        print(name,trial,{k:round(v['cpu_seconds'],6) for k,v in pair.items()},flush=True)
        (work/'summary.json').write_text(json.dumps(cell,indent=2)+'\n')
    cell['best']={k:min(t[k]['cpu_seconds'] for t in cell['trials']) for k in ('baseline','candidate','floor')}
    (work/'request.json').unlink()
    (work/'floor.json').unlink()
    record['cells'].append(cell)
    (out/'summary.json').write_text(json.dumps(record,indent=2)+'\n')

