use kassiber_store::rusqlite::{Connection, params_from_iter, types::{Value,ValueRef}};
use std::hint::black_box;
struct Param<'a>(ValueRef<'a>);
impl kassiber_store::rusqlite::ToSql for Param<'_> {
 fn to_sql(&self)->kassiber_store::rusqlite::Result<kassiber_store::rusqlite::types::ToSqlOutput<'_>> {Ok(kassiber_store::rusqlite::types::ToSqlOutput::Borrowed(self.0))}
}
fn main() {
    let reuse=std::env::args().nth(1).as_deref()==Some("reuse");
    let c=Connection::open_in_memory().unwrap();
    c.execute_batch("CREATE TABLE t(a,b,c,d,e,f,g,h,i,j,k,l);BEGIN").unwrap();
    let mut statement=c.prepare("INSERT INTO t VALUES(?,?,?,?,?,?,?,?,?,?,?,?)").unwrap();
    let rows:Vec<[Value;12]>=(0..100_000).map(|i| [Value::Text(i.to_string()),Value::Text("workspace".into()),Value::Text("profile".into()),Value::Text(format!("transaction-{i}")),Value::Text(format!("observation-{i}")),Value::Text("time".into()),Value::Text("BTC".into()),Value::Text("wallet".into()),Value::Text("location".into()),Value::Integer(i),Value::Text("included".into()),Value::Text("created".into())]).collect();
    let mut bound:[Option<ValueRef<'_>>;12]=[None;12];
    for row in &rows {
        if reuse {
            for (index,prior) in bound.iter_mut().enumerate() {
                let value=ValueRef::from(&row[index]);
                let same=prior.is_some_and(|prior| match(prior,value) {(ValueRef::Real(a),ValueRef::Real(b))=>a.to_bits()==b.to_bits(),_=>prior==value});
                if !same { statement.raw_bind_parameter(index+1,Param(value)).unwrap();*prior=Some(value); }
            }
            statement.raw_execute().unwrap();
        } else { statement.execute(params_from_iter(row)).unwrap(); }
    }
    black_box(c.query_row("SELECT COUNT(*) FROM t",[],|r|r.get::<_,i64>(0)).unwrap());
}
